import{_ as t,o as r,c as a,ae as n}from"./chunks/framework.Dzr56EFm.js";const d=JSON.parse('{"title":"产品发布 - 2026-07-12","description":"","frontmatter":{"date":"2026-07-12T00:00:00.000Z","category":"Product"},"headers":[],"relativePath":"daily/2026-07-12-product.md","filePath":"daily/2026-07-12-product.md"}'),e={name:"daily/2026-07-12-product.md"};function s(i,o,p,g,h,l){return r(),a("div",null,[...o[0]||(o[0]=[n('<h1 id="产品发布-2026-07-12" tabindex="-1">产品发布 - 2026-07-12 <a class="header-anchor" href="#产品发布-2026-07-12" aria-label="Permalink to &quot;产品发布 - 2026-07-12&quot;">​</a></h1><blockquote><p>AI App、工具、浏览器、搜索、Copilot</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日产品发布领域主要动态集中在Notion和Figma的更新。Notion 3.4版本新增6项特性，AI功能升级至GPT-5.4模型，提升长任务处理能力；Figma推出AI工具，挑战Canva和Adobe。最值得关注的是Notion AI的升级和Figma的AI驱动工具发布，这标志着AI技术在产品协作和设计领域的进一步应用。</p><hr><h3 id="_1-notion-3-4更新的6个新特性全面教程与指南" tabindex="-1">1. Notion 3.4更新的6个新特性全面教程与指南 <a class="header-anchor" href="#_1-notion-3-4更新的6个新特性全面教程与指南" aria-label="Permalink to &quot;1. Notion 3.4更新的6个新特性全面教程与指南&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.youtube.com/watch?v=VDwpfCSAu3I" target="_blank" rel="noreferrer">6 NEW Features in the Notion 3.4 Update | Full Tutorial &amp; Guide</a></p><p><strong>一句话摘要</strong>: 介绍Notion 3.4版本中的6个新特性</p><p><strong>能解决什么问题</strong>: 提高个人和团队的工作效率和信息管理能力</p><p><strong>产品应用</strong>: 可以应用到实际产品中，如项目管理、会议记录和日常任务管理</p><p><strong>示例场景</strong>: 使用Notion AI自动生成会议纪要和行动列表</p><hr><h3 id="_2-notion-ai-新功能更新-matthias-frank" tabindex="-1">2. Notion AI 新功能更新 - Matthias Frank <a class="header-anchor" href="#_2-notion-ai-新功能更新-matthias-frank" aria-label="Permalink to &quot;2. Notion AI 新功能更新 - Matthias Frank&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://matthiasfrank.de/en/notion-updates" target="_blank" rel="noreferrer">Notion Updates &amp; New Features - Matthias Frank</a></p><p><strong>一句话摘要</strong>: Notion AI新增GPT-5.4模型，提升长任务处理能力。</p><p><strong>能解决什么问题</strong>: 解决复杂任务规划和执行中的信息处理问题。</p><p><strong>产品应用</strong>: 适用于需要自动化和协作的项目管理和信息整理。</p><p><strong>示例场景</strong>: 自动化生成晨报或总结复杂项目讨论。</p><hr><h3 id="_3-figma发布新的ai工具-用于创建网站和应用" tabindex="-1">3. Figma发布新的AI工具，用于创建网站和应用 <a class="header-anchor" href="#_3-figma发布新的ai工具-用于创建网站和应用" aria-label="Permalink to &quot;3. Figma发布新的AI工具，用于创建网站和应用&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://techcrunch.com/2025/05/07/figma-releases-new-ai-powered-tools-for-creating-sites-app-prototypes-and-marketing-assets" target="_blank" rel="noreferrer">Figma releases new AI-powered tools for creating sites, app ...</a></p><p><strong>一句话摘要</strong>: Figma推出AI驱动的网站和应用创建工具，挑战Canva和Adobe。</p><p><strong>能解决什么问题</strong>: 解决设计师和营销人员创建网站、应用和营销素材的效率问题。</p><p><strong>产品应用</strong>: 可以应用于实际产品设计中，提高设计和营销工作的自动化和效率。</p><p><strong>示例场景</strong>: 设计师使用Figma Sites快速搭建并发布品牌网站。</p><hr><h3 id="_4-notion文档更新日志" tabindex="-1">4. Notion文档更新日志 <a class="header-anchor" href="#_4-notion文档更新日志" aria-label="Permalink to &quot;4. Notion文档更新日志&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://developers.notion.com/page/changelog" target="_blank" rel="noreferrer">Changelog - Notion Docs</a></p><p><strong>一句话摘要</strong>: Notion扩展AI助手功能并发布新版SDK。</p><p><strong>能解决什么问题</strong>: 解决AI助手在Notion中的访问限制和功能不足问题。</p><p><strong>产品应用</strong>: 可以应用到需要Notion集成AI助手的产品中，提升自动化和效率。</p><p><strong>示例场景</strong>: 企业团队使用AI助手直接查询数据库。</p><hr><h3 id="_5-数字-ai-23-3版本工作流概览" tabindex="-1">5. 数字.ai 23.3版本工作流概览 <a class="header-anchor" href="#_5-数字-ai-23-3版本工作流概览" aria-label="Permalink to &quot;5. 数字.ai 23.3版本工作流概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://docs.digital.ai/release/docs/how-to/workflows-overview" target="_blank" rel="noreferrer">Workflows Overview · digital.ai Release</a></p><p><strong>一句话摘要</strong>: 数字.ai 23.3引入自助服务工作流简化应用上线流程。</p><p><strong>能解决什么问题</strong>: 解决开发者对工具了解有限时如何轻松上线应用的问题。</p><p><strong>产品应用</strong>: 可以应用于实际产品中，通过工作流自动化部署和优化应用。</p><p><strong>示例场景</strong>: 使用工作流自动化CI/CD流程，提高软件发布效率。</p><hr><h3 id="_6-16项新notion更新概览-16分钟" tabindex="-1">6. 16项新Notion更新概览（16分钟） <a class="header-anchor" href="#_6-16项新notion更新概览-16分钟" aria-label="Permalink to &quot;6. 16项新Notion更新概览（16分钟）&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.youtube.com/watch?v=GnonRPjbzZY" target="_blank" rel="noreferrer">16 New Notion Updates (in just 16 minutes)</a></p><p><strong>一句话摘要</strong>: Notion新增16项功能，包括AI阅读页面历史等。</p><p><strong>能解决什么问题</strong>: 提高工作效率，简化团队协作和知识管理。</p><p><strong>产品应用</strong>: 适用于需要团队协作和知识管理的企业和个人。</p><p><strong>示例场景</strong>: 团队成员通过Notion AI追踪项目变更历史。</p><hr><h3 id="_7-2026年我真正在使用的9个强大的notion更新" tabindex="-1">7. 2026年我真正在使用的9个强大的Notion更新 <a class="header-anchor" href="#_7-2026年我真正在使用的9个强大的notion更新" aria-label="Permalink to &quot;7. 2026年我真正在使用的9个强大的Notion更新&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.youtube.com/watch?v=5RlFIiaMsBc" target="_blank" rel="noreferrer">9 Powerful Notion Updates I&#39;m ACTUALLY Using in 2026 ... - YouTube</a></p><p><strong>一句话摘要</strong>: 介绍了Notion在2026年的新功能及其实际应用</p><p><strong>能解决什么问题</strong>: 解决了会议记录和笔记整合的问题</p><p><strong>产品应用</strong>: 可以应用到实际产品中，提高会议记录效率</p><p><strong>示例场景</strong>: 使用Notion的AI会议笔记功能记录会议内容</p><hr><h3 id="_8-产品副驾驶-软件产品团队的ai助手" tabindex="-1">8. 产品副驾驶 - 软件产品团队的AI助手 <a class="header-anchor" href="#_8-产品副驾驶-软件产品团队的ai助手" aria-label="Permalink to &quot;8. 产品副驾驶 - 软件产品团队的AI助手&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://product-copilot.ai" target="_blank" rel="noreferrer">Product Copilot – AI Assistant for Software Product Teams</a></p><p><strong>一句话摘要</strong>: Product Copilot是集成在Jira和Confluence中的AI助手，帮助产品团队提高效率。</p><p><strong>能解决什么问题</strong>: 解决产品团队在用户故事一致性、协作和产品开发速度上的问题。</p><p><strong>产品应用</strong>: 适用于需要优化产品管理流程和提高工作效率的实际产品团队。</p><p><strong>示例场景</strong>: 产品负责人使用Product Copilot创建清晰的任务票和维护文档。</p><hr><h3 id="_9-chatgpt团队推出ai社交媒体应用sora2" tabindex="-1">9. ChatGPT团队推出AI社交媒体应用Sora2 <a class="header-anchor" href="#_9-chatgpt团队推出ai社交媒体应用sora2" aria-label="Permalink to &quot;9. ChatGPT团队推出AI社交媒体应用Sora2&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.youtube.com/watch?v=ATz5hMe8Xsw" target="_blank" rel="noreferrer">Creators Behind ChatGPT Launch New AI Social Media App Called Sora2 | 10 News+</a></p><p><strong>一句话摘要</strong>: ChatGPT背后的公司Open AI推出了新的AI社交媒体应用Sora2。</p><p><strong>能解决什么问题</strong>: 解决用户创作高质量视频内容的复杂性和时间成本问题。</p><p><strong>产品应用</strong>: 可以应用到视频创作领域，用户通过简单提示生成视频。</p><p><strong>示例场景</strong>: 用户利用Sora2创建包含自己形象的超现实短视频。</p><hr><h3 id="_10-微软copilot-面向组织的ai工具" tabindex="-1">10. 微软Copilot | 面向组织的AI工具 <a class="header-anchor" href="#_10-微软copilot-面向组织的ai工具" aria-label="Permalink to &quot;10. 微软Copilot | 面向组织的AI工具&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.microsoft.com/en-us/microsoft-copilot/organizations" target="_blank" rel="noreferrer">Microsoft Copilot | AI Tools for Organizations</a></p><p><strong>一句话摘要</strong>: 微软Copilot提供基于聊天的生成式AI交互，助力组织和企业。</p><p><strong>能解决什么问题</strong>: 提高工作效率，增强安全性，促进团队协作。</p><p><strong>产品应用</strong>: 可应用于企业日常运营，如文档编辑、数据分析、代码编写等。</p><p><strong>示例场景</strong>: 企业员工使用Microsoft 365 Copilot处理文档和邮件。</p><hr>',75)])])}const u=t(e,[["render",s]]);export{d as __pageData,u as default};
